UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (4369, 'Ніндзя з кеккей генкай починають зникати в усіх країнах, і підозра падає на Країну Вогню. За наказом Цунаде, Какасі має бути принесений у жертву, щоб запобігти тотальній війні. Успадкувавши талісмани, залишені Какасі, Наруто бореться з друзями та ворогами, щоб запобігти його загибелі, водночас змінюючи погляди тих, хто успадкував волю вогню.'),
  (4371, 'Отримавши завдання схопити Мукаде, зниклого ніна, Наруто Узумакі вирушає до колись славетних історичних руїн «Оуран», де переслідує та заганяє в кут відступника. Метою Мукаде виявляється сплячий лей-лайн усередині руїн; він вивільняє його силу, і світло огортає Наруто, переносячи його в минуле — за 20 років до початку подій серіалу. Прокинувшись, Наруто зустрічає Четвертого Хокаге, Мінато Намікадзе.'),
  (4375, 'Белль, Чудовисько, Люм''єр, Когсворт та решта кумедних мешканців замку використовують свою уяву, щоб вирушити у три чарівні казкові пригоди. У «Ідеальному світі» Белль і Чудовисько вчаться прощати. У «Помилці Фіфі» дівчина Люм''єра ревнує його до Белль. А в «Зламаному крилі» Чудовисько вчиться бути добрим до пораненого пташеняти.'),
  (4382, 'Коли татові несподівано доводиться замінити маму й зробити зачіску доньці Зурі перед важливою подією, те, що здається простим завданням, виявляється зовсім не таким — адже це волосся живе власним життям!'),
  (4462, 'Спустошена загибеллю своєї чотирирічної доньки, вчителька середньої школи з жахом виявляє, що її учні зовсім не такі невинні, як вона вважала.'),
  (4560, 'Білл Вітні стурбований тим, що він відрізняється від своєї сестри та батьків. Вони спілкуються з іншими представниками вищого класу, тоді як Білл простіший у стосунках. Навіть його дівчина здається трохи дивною. Усе стає зрозумілим, коли Білл повертається додому й застає вечірку в самому розпалі.'),
  (4587, 'Матір-одиначку ґвалтує невидима сила. Її психіатр вважає, що переживання пов''язані з дитячою травмою, тоді як вона знає — тут діє щось надприродне.'),
  (4653, 'Молодий британський солдат має знайти шлях до безпеки після того, як його підрозділ випадково залишив його під час заворушень на вулицях Белфаста.'),
  (4993, 'Короткометражка Піксар про коробку бюро знахідок і невидиме створіння, що ховається всередині.'),
  (5125, 'Непримітний старшокласник несподівано захоплюється вільнодумною новенькою, чиї нетрадиційні погляди змінюють їхнє бачення себе… і навколишнього світу.'),
  (5177, 'Коли улюбленого пса юного Віктора, Спаркі (який знімається у домашніх фільмах жахів Віктора), збиває машина, Віктор вирішує повернути його до життя єдиним відомим йому способом. Але коли «монстр» із болтами на шиї сіє хаос і жах серед сусідів Віктора, хлопець має переконати їх (і своїх батьків), що попри свій вигляд, Спаркі залишається тим самим вірним і відданим другом, яким був завжди.'),
  (5218, 'Вінні-Пух розгублюється, коли Крістофер Робін залишає йому записку про те, що повернувся до школи після канікул. Тож Пух, П''ятачок, Тигруля, Іа-Іа та Кролик вирушають на пошуки Крістофера Робіна, що переростає у велику пригоду.'),
  (5263, 'Перший погляд зсередини на реалії світу професійного «аматорського» порно та безперервний потік 18-19-річних дівчат, які потрапляють у цю індустрію.'),
  (5308, 'Історія життя на нашій планеті від людини, яка бачила більше природного світу, ніж будь-хто інший. За понад 90 років Аттенборо відвідав кожен континент, досліджуючи дикі куточки нашої планети та документуючи живий світ у всьому його різноманітті та дивовижності. Звертаючись до найбільших викликів, що стоять перед життям на нашій планеті, фільм несе потужне послання надії для майбутніх поколінь.'),
  (5485, 'Ерік О''Нілл, молодий спеціаліст із спостереження у ФБР, вважає, що здійснює свою мрію стати повноцінним агентом завдяки несподіваному підвищенню та призначенню помічником Роберта Ханссена, видатного старшого агента з 25-річним стажем у ФБР. Проте незабаром він дізнається, що справжня причина його підвищення — здобути довіру Ханссена та знайти докази того, що той є зрадником. Сповнений рішучості викрити підозрюваного подвійного агента, О''Нілл опиняється у смертельній грі шпигуна проти шпигуна, де ніщо не є тим, чим здається.'),
  (5673, 'Група мексиканців виявляє, що їхні земельні претензії у США відхилено, а всі записи знищено під час пожежі в суді. Їхній лідер, Луїс Чама, закликає використати силу, щоб повернути свої землі. Багатий землевласник, який претендує на те саме, вирішує найняти банду вбивць разом із Джо Кіддом, щоб вистежити Чаму.')
) AS v(id, overview_uk) WHERE content.id = v.id;
